109	func (f *Fetcher) Resolve(req *base.Request) error {
110		f.mu.Lock()
111		defer f.mu.Unlock()
112		if f.torrent != nil {
113			f.safeDrop()
114			f.torrent = nil
115			f.storage = nil
116			f.torrentReady.Store(false)
117		}
118		f.meta.Req = req
119		if err := f.addTorrent(req); err != nil {
120			return err
121		}
122		f.updateRes()
123		return nil
124	}
