126	func (f *Fetcher) Start() (err error) {
127		f.mu.Lock()
128		defer f.mu.Unlock()
129		if f.meta.Opts == nil || f.meta.Opts.Path == "" {
130			return errors.New("download directory is required when starting a torrent")
131		}
132		if err := f.torrentDropCtx.Err(); err != nil {
133			return err
134		}
135		if !f.torrentReady.Load() {
136			if err = f.addTorrent(f.meta.Req); err != nil {
137				return
138			}
139		}
140	
141		path := f.meta.Opts.Path
142		if err := os.MkdirAll(path, 0755); err != nil {
143			return err
144		}
145		hashes, err := f.storage.bind(storage.NewFileClientOpts{
146			ClientBaseDir: path,
147			FilePathMaker: func(opts storage.FilePathMakerOpts) string {
148				_, name := torrentFileLayout(opts.Info, *opts.File)
149				return name
150			},
151		})
152		if err != nil {
153			return err
154		}
155		if hashes != nil {
156			// File storage infers completion from final file names and sizes. Verify
157			// before publishing that state, or peers can see an unverified file as
158			// complete and disconnect before a damaged piece is discovered.
159			// Late v2 hashes schedule their own initial checks through the library.
160			changes := f.torrent.SubscribePieceStateChanges()
161			defer changes.Close()
162			for i, known := range hashes {
163				if !known {
164					continue
165				}
166				if err := f.torrentDropCtx.Err(); err != nil {
167					return err
168				}
169				if err := f.torrent.Piece(i).VerifyDataContext(f.torrentDropCtx); err != nil {
170					return err
171				}
172				// VerifyDataContext can return while the result is still being
173				// written to storage. Wait for it before refreshing completion.
174				for {
175					state := f.torrent.Piece(i).State()
176					if !state.Hashing && !state.QueuedForHash && !state.Marking {
177						break
178					}
179					select {
180					case <-changes.Values:
181					case <-f.torrentDropCtx.Done():
182						return f.torrentDropCtx.Err()
183					case <-f.torrent.Closed():
184						return errors.New("torrent closed during verification")
185					}
186				}
187			}
188			for i := range hashes {
189				f.torrent.Piece(i).UpdateCompletion()
190			}
191		}
192	
193		files := f.torrent.Files()
194		// If the user does not specify the file to download, all files will be downloaded by default
195		if f.data.Progress == nil {
196			if len(f.meta.Opts.SelectFiles) == 0 {
197				f.meta.Opts.SelectFiles = make([]int, len(files))
198				for i := range files {
199					f.meta.Opts.SelectFiles[i] = i
200				}

