322	// TestFetcher_Patch tests the Patch functionality for BT fetcher.
323	// It tests modifying selected files after Resolve (without downloading).
324	func TestFetcher_Patch(t *testing.T) {
325		f := buildFetcher(t)
326	
327		// Resolve a multi-file torrent
328		err := f.Resolve(&base.Request{
329			URL: "./testdata/test.torrent",
330		})
331		if err != nil {
332			t.Fatalf("Resolve failed: %v", err)
333		}
334	
335		// Resolution describes files without choosing download options.
336		meta := f.Meta()
337		if len(meta.Res.Files) != 3 {
338			t.Fatalf("Expected 3 files, got %d", len(meta.Res.Files))
339		}
340		if meta.Opts != nil {
341			t.Fatal("Resolve should not assign download options")
342		}
343	
344		// Total size of all files: 107484864
345		totalSize := int64(107484864)
346		if meta.Res.Size != totalSize {
347			t.Fatalf("Expected total size %d, got %d", totalSize, meta.Res.Size)
348		}
349	
350		t.Run("Patch with valid indices", func(t *testing.T) {
351			// Select only file 0 and 2 (c.txt and a.txt)
352			err := f.Patch(nil, &base.Options{
353				SelectFiles: []int{0, 2},
354			})
355			if err != nil {
356				t.Fatalf("Patch failed: %v", err)
357			}
358	
359			meta := f.Meta()
360			if !reflect.DeepEqual(meta.Opts.SelectFiles, []int{0, 2}) {
361				t.Errorf("Expected SelectFiles [0, 2], got %v", meta.Opts.SelectFiles)
362			}
363	
364			// Size should be recalculated: c.txt (98501754) + a.txt (78114) = 98579868
365			expectedSize := int64(98501754 + 78114)
366			if meta.Res.Size != expectedSize {
367				t.Errorf("Expected size %d, got %d", expectedSize, meta.Res.Size)
368			}
369		})
370	
371		t.Run("Patch with invalid indices are silently ignored", func(t *testing.T) {
372			// Mix of valid (0, 1) and invalid (-1, 5, 100) indices
373			err := f.Patch(nil, &base.Options{
374				SelectFiles: []int{-1, 0, 5, 1, 100},
375			})
376			if err != nil {
377				t.Fatalf("Patch should not return error for invalid indices: %v", err)
378			}
379	
380			meta := f.Meta()
381			// Only valid indices 0 and 1 should remain
382			if !reflect.DeepEqual(meta.Opts.SelectFiles, []int{0, 1}) {
383				t.Errorf("Expected SelectFiles [0, 1], got %v", meta.Opts.SelectFiles)
384			}
385	
386			// Size should be: c.txt (98501754) + b.txt (8904996) = 107406750
387			expectedSize := int64(98501754 + 8904996)
388			if meta.Res.Size != expectedSize {
389				t.Errorf("Expected size %d, got %d", expectedSize, meta.Res.Size)
390			}
391		})
392	
393		t.Run("Patch with all invalid indices results in empty selection", func(t *testing.T) {
394			err := f.Patch(nil, &base.Options{
395				SelectFiles: []int{-5, 10, 999},
396			})
397			if err != nil {
398				t.Fatalf("Patch should not return error: %v", err)
399			}
400	
401			meta := f.Meta()
402			if len(meta.Opts.SelectFiles) != 0 {
403				t.Errorf("Expected empty SelectFiles, got %v", meta.Opts.SelectFiles)
404			}
405	
406			// Note: CalcSize with empty selectFiles calculates total size of all files
407			// This is by design - empty selection in CalcSize means "all files"
408			// But SelectFiles being empty means no files are selected for download
409			if meta.Res.Size != totalSize {
410				t.Errorf("Expected size %d (CalcSize with empty slice = all files), got %d", totalSize, meta.Res.Size)
411			}
412		})
413	
414		t.Run("Patch with nil opts does nothing", func(t *testing.T) {
415			// First set a known state
416			f.Patch(nil, &base.Options{SelectFiles: []int{1}})
417			prevSelectFiles := f.Meta().Opts.SelectFiles
418	
419			// Patch with nil opts
420			err := f.Patch(nil, nil)
421			if err != nil {
422				t.Fatalf("Patch with nil opts should not fail: %v", err)
423			}
424	
425			// Should remain unchanged
426			if !reflect.DeepEqual(f.Meta().Opts.SelectFiles, prevSelectFiles) {
427				t.Errorf("SelectFiles should remain unchanged after nil opts Patch")
428			}
429		})
430	
431		t.Run("Patch progress array is resized", func(t *testing.T) {
432			btFetcher := f.(*Fetcher)
433			// Initialize progress array
434			btFetcher.data.Progress = make(fetcher.Progress, 3)
435	
436			err := f.Patch(nil, &base.Options{
437				SelectFiles: []int{0, 2},
438			})
439			if err != nil {
440				t.Fatalf("Patch failed: %v", err)
441			}
442	
443			if len(btFetcher.data.Progress) != 2 {
444				t.Errorf("Expected Progress length 2, got %d", len(btFetcher.data.Progress))
445			}
446		})
447	}
