752	func (f *Fetcher) addTorrent(req *base.Request) (err error) {
753		f.ctl.GetConfig(&f.config)
754		if err = base.ParseReqExtra[bt.ReqExtra](req); err != nil {
755			return
756		}
757		schema := util.ParseSchema(req.URL)
758		privateTorrent := false
759		var spec *torrent.TorrentSpec
760		if schema == "MAGNET" {
761			spec, err = torrent.TorrentSpecFromMagnetUri(req.URL)
762			if err != nil {
763				return
764			}
765		} else {
766			var reader io.Reader
767			if schema == "FILE" {
768				fileUrl, _ := url.Parse(req.URL)
769				filePath := fileUrl.Path
770				if runtime.GOOS == "windows" && len(filePath) > 2 && filePath[0] == '/' && filePath[2] == ':' {
771					filePath = filePath[1:]
772				}
773				filePath = filepath.FromSlash(filePath)
774				reader, err = os.Open(filePath)
775				if err != nil {
776					return
777				}
778				defer reader.(io.Closer).Close()
779			} else if schema == "DATA" {
780				_, data := util.ParseDataUri(req.URL)
781				reader = bytes.NewBuffer(data)
782			} else {
783				reader, err = os.Open(req.URL)
784				if err != nil {
785					return
786				}
787				defer reader.(io.Closer).Close()
788			}
789	
790			var metaInfo *metainfo.MetaInfo
791			metaInfo, err = metainfo.Load(reader)
792			// Hotfix for https://github.com/anacrolix/torrent/issues/992, ignore "expected EOF" error
793			// TODO remove this after the issue is fixed
794			if err != nil && !strings.Contains(err.Error(), "expected EOF") {
795				return err
796			}
797	
798			info, er := metaInfo.UnmarshalInfo()
799			if er != nil {
800				return er
801			}
802	
803			if info.Private != nil && *info.Private {
804				privateTorrent = true
805			}
806			spec, err = torrent.TorrentSpecFromMetaInfoErr(metaInfo)
807			if err != nil {
808				return
809			}
810		}
811		// Do not add external tracker to a private torrent.
812		if !privateTorrent {
813			// use map to deduplicate
814			trackers := make(map[string]bool)
815			if req.Extra != nil {
816				extra := req.Extra.(*bt.ReqExtra)
817				if len(extra.Trackers) > 0 {
818					for _, tracker := range extra.Trackers {
819						trackers[tracker] = true
820					}
821				}
822			}
823			for _, tracker := range f.config.effectiveTrackers() {
824				trackers[tracker] = true
825			}
826			if len(trackers) > 0 {
827				for tracker := range trackers {
828					spec.Trackers = append(spec.Trackers, []string{tracker})
829				}
830			}
831		}
832		s := &deferredFileStorage{}
833		spec.Storage = s
834		var added bool
835		f.torrent, added, err = f.addTorrentSpec(spec)
836		if err != nil {
837			return err
838		}
839		if !added {
840			f.torrent = nil
841			return errors.New("torrent is already active")
842		}
843		f.storage = s
844		f.torrent.DisallowDataDownload()
845		// Extra trackers must be available while magnet metadata is still missing;
846		// they may be the only way to discover a peer that can provide it.
847		select {
848		case <-f.torrent.GotInfo():
849		case <-f.torrentDropCtx.Done():
850			f.safeDrop()
851			return f.torrentDropCtx.Err()
852		case <-f.torrent.Closed():
853			return errors.New("torrent closed during resolution")
854		}
855		f.torrentReady.Store(true)
856	
857		return
858	}
