860	func (f *Fetcher) seedRadio() float64 {
861		var bytesRead int64
862		if f.Meta().Res != nil {
863			bytesRead = f.Meta().Res.Size
864		} else {
865			bytesRead = 0
866		}
867		if bytesRead <= 0 {
868			return 0
869		}
870	
871		return float64(f.data.SeedBytes) / float64(bytesRead)
872	}
