881	func closeClient() error {
882		lock.Lock()
883		defer lock.Unlock()
884	
885		if closeFunc != nil {
886			closeFunc()
887		}
888		if client != nil {
889			errs := client.Close()
890			if len(errs) > 0 {
891				return errs[0]
892			}
893			client = nil
894			closeCtx = nil
895			closeFunc = nil
896		}
897		return nil
898	}
